script:
frappe.ui.form.on('Supplier', {
    supplier_name: function(frm) {
        if (frm.doc.supplier_name) {
            // Get first character and convert to uppercase
            let initial = frm.doc.supplier_name.charAt(0).toUpperCase();

            // Set value to custom field
            frm.set_value('custom_initial', initial);
        } else {
            // Clear if empty
            frm.set_value('custom_initial', '');
        }
    }
});

frappe.ui.form.on('Customer', {
    customer_name: function(frm) {
        if (frm.doc.customer_name) {
            // Get first character and convert to uppercase
            let initial = frm.doc.customer_name.charAt(0).toUpperCase();

            // Set value to custom field
            frm.set_value('custom_cn_initial', initial);
        } else {
            // Clear if empty
            frm.set_value('custom_cn_initial', '');
        }
    }
});

frappe.ui.form.on('Item', {
    validate: function(frm) {
        let value = frm.doc.item_code || "";

        if (value.length !== 9) {
            frappe.throw("Item Code must be exactly 9 characters (format legacy: XXX-00000)");
        }
    }
});

frappe.ui.form.on('User', {
    refresh: function(frm) {
        setTimeout(function() {
            hide_roles();
            filter_modules();
            hide_bulk_buttons();
        }, 700);
    }
});

function hide_roles() {
    const blacklist = ['System Manager', 'Script Manager'];

    blacklist.forEach(function(role) {
        $(`[data-fieldname="roles_html"] input[data-unit="${role}"]`)
            .closest('div.unit-checkbox')
            .hide();
    });
}

function filter_modules() {
    const whitelist = [
        'Accounts',
        'Buying',
        'Selling',
        'Stock',
        'Core'
    ];

    $('[data-fieldname="modules_html"] div.unit-checkbox').each(function() {
        const unit = $(this).find('input').data('unit');
        if (!whitelist.includes(unit)) {
            $(this).hide();
        }
    });
}

function hide_bulk_buttons() {
    $('div.bulk-select-options').hide();
}

// Immediate alert when user manually changes rate on an item row
frappe.ui.form.on('Sales Invoice Item', {
	rate(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		if (!row.item_code || !row.warehouse || row.is_free_item) return;

		frappe.call({
			method: 'frappe.client.get_value',
			args: {
				doctype: 'Bin',
				filters: { item_code: row.item_code, warehouse: row.warehouse },
				fieldname: 'valuation_rate'
			},
			callback(r) {
				if (!r.message) return;
				const val_rate = flt(r.message.valuation_rate);
				if (val_rate > 0 && flt(row.rate) < val_rate) {
					frappe.show_alert({
						message: __('Row {0} ({1}): Rate {2} is below valuation rate {3}', [
							row.idx,
							row.item_name,
							format_currency(row.rate, frm.doc.currency),
							format_currency(val_rate, frm.doc.currency)
						]),
						indicator: 'orange'
					}, 8);
				}
			}
		});
	}
});

// Below-cost check on submit: compare against live Bin valuation_rate
// (not saved incoming_rate) and show a modal, matching Frappe's native
// validation dialogs. First submit click is blocked so the popup stands
// out; user must close it and click Submit again to confirm and proceed.
frappe.ui.form.on('Sales Invoice', {
	before_submit(frm) {
		const rows = (frm.doc.items || []).filter(
			row => !row.is_free_item && row.item_code && row.warehouse
		);
		if (!rows.length) return;

		return Promise.all(
			rows.map(row =>
				frappe.call({
					method: 'frappe.client.get_value',
					args: {
						doctype: 'Bin',
						filters: { item_code: row.item_code, warehouse: row.warehouse },
						fieldname: 'valuation_rate'
					}
				}).then(r => ({ row, val_rate: flt(r.message && r.message.valuation_rate) }))
			)
		).then(results => {
			const below = results.filter(({ row, val_rate }) => val_rate > 0 && flt(row.rate) < val_rate);

			if (!below.length) {
				frm.__below_cost_ack = null;
				return;
			}

			// Signature of the current below-cost state -- if the user already saw
			// this exact popup and clicked Submit again, let it through. If rates
			// changed since, treat it as a new warning and block again.
			const signature = below
				.map(({ row, val_rate }) => `${row.item_code}|${row.warehouse}|${row.rate}|${val_rate}`)
				.sort()
				.join(';');

			if (frm.__below_cost_ack === signature) {
				return;
			}

			frm.__below_cost_ack = signature;
			frappe.validated = false;

			const warnings = below.map(({ row, val_rate }) =>
				`<b>Row ${row.idx} — ${row.item_name}</b><br>` +
				`Selling rate: ${format_currency(row.rate, frm.doc.currency)} | ` +
				`Valuation rate: ${format_currency(val_rate, frm.doc.currency)}`
			);

			frappe.msgprint({
				title: __('Selling Below Cost'),
				message:
					__('The following items are priced below their valuation rate. Click Submit again to confirm.') +
					'<br><br>' +
					warnings.join('<br><br>'),
				indicator: 'orange'
			});
		});
	}
});

// Core sales_invoice.js resets update_stock's read_only flag on every
// refresh (frm.set_df_property('update_stock', 'read_only', frm.doc.has_subcontracted)),
// which clobbers the Customize Form setting. Client Scripts load after all
// bundled app JS, so this reliably overrides it.
frappe.ui.form.on('Sales Invoice', {
	refresh: function (frm) {
		frm.set_df_property('update_stock', 'read_only', 1);
	}
});
